# powerboost: each rule of src/quest/combat/powerboost.cpp, src/runtime/patch/powerboost_rules.h and powerboost_core.h removed or bent once;
# src/quest/tests/powerboost_test.cpp must
# fail on every one. Sourced by ../mutants.sh, which defines `runm <name> <file> <sed>`. The entry's text (powerboost_thunk.inc) is judged by
# check/powerboost.sh, not by the host test; this list does not cover it.
P=src/quest/combat/powerboost.cpp
C=src/quest/combat/powerboost_core.h
# the shared rules (#2339), also killed by the PC GTest, runtime/tests/test_powerboost_rules.cpp
R=src/runtime/patch/powerboost_rules.h
Q=src/quest/sentinel/quest_config.cpp
# install: all three words or none, loud, in order
runm pb_no_rollback        $P 's/back = rows\[k\].hook->Remove() == sentinel::GotStatus::kOk \&\& back;/(void)k;/'
runm pb_rollback_quiet     $P 's/{"failed_hook", rows\[done\].name}, //'
runm pb_swallow_unguarded  $P 's/why = "Heal.s GLOB_DAT word was not hooked";/why = nullptr;/'
runm pb_no_sender_check    $P 's/(!ok || sendWord != base + pins.sendFn)/(false \&\& !ok \&\& sendWord != 0)/'
runm pb_no_bl_check        $P 's/(!ok || call != kConeCallWord)/(false \&\& !ok \&\& call != 0)/'
runm pb_no_net_tick_check  $P 's/: !(registrar != nullptr ? registrar : \&DefaultRegistrar)(\&NetTick) ? /: ((void)(registrar != nullptr ? registrar : \&DefaultRegistrar), false) ? /'
runm pb_unresolved_goes_on $P 's/if (!have \&\& stage >= kSwallow) {/if (!have \&\& false) {/'
runm pb_cone_ret_unset     $P 's/__atomic_store_n(\&nevr_combat_pb_cone_ret, base + pins.coneRet, __ATOMIC_RELEASE);.*$//'
runm pb_cone_ret_wrong     $P 's/__atomic_store_n(\&nevr_combat_pb_cone_ret, base + pins.coneRet,/__atomic_store_n(\&nevr_combat_pb_cone_ret, base + pins.coneCall,/'
runm pb_cone_ret_kept      $P '/^        __atomic_store_n(\&nevr_combat_pb_cone_ret, std::uintptr_t{0}, __ATOMIC_RELEASE);$/d'
runm pb_cone_flag_kept     $P '/^      if (r != sentinel::GotStatus::kOk) {$/{n;s/g_cone.store(false, std::memory_order_release);//}'
runm pb_refusal_quiet      $P 's/sentinel::LogFields(sentinel::LogLevel::kError, "combat_powerboost_cone_off",/sentinel::LogFields(sentinel::LogLevel::kInfo, "combat_powerboost_cone_off",/'
runm pb_hook_refusal_quiet $P 's/sentinel::LogFields(status == sentinel::GotStatus::kOk ? sentinel::LogLevel::kInfo : sentinel::LogLevel::kError, "combat_powerboost_hook",/sentinel::LogFields(sentinel::LogLevel::kInfo, "combat_powerboost_hook",/'
runm pb_partial_is_info    $P 's/sentinel::LogFields(full ? sentinel::LogLevel::kInfo : sentinel::LogLevel::kError, "combat_powerboost_install",/sentinel::LogFields(sentinel::LogLevel::kInfo, "combat_powerboost_install",/'
runm pb_stage_range_hi     $P 's/if (stage < kRead || stage > kCone) {/if (stage < kRead) {/'
runm pb_stage_range_lo     $P 's/if (stage < kRead || stage > kCone) {/if (stage > kCone) {/'
runm pb_runs_twice         $P 's/if (g_ran.exchange(true, std::memory_order_acq_rel)) {/if (false) {/'
runm pb_build_id_ignored   $P 's/if (std::strcmp(id, pinned::LibR15PatchedBuildId()) != 0) return Refused/if (false) return Refused/'
runm pb_no_tick            $P 's/if (!tick::Add(\&GameTick)) return Refused/if (false) return Refused/'
# the arena scope
runm pb_scope_always       $P 's/^inline bool Scoped() noexcept { return g_inScope.load(std::memory_order_acquire); }$/inline bool Scoped() noexcept { return true; }/'
runm pb_scope_lobby_off    $P 's/^  const bool in = scope::InCombatOrLobby(look);$/  const bool in = scope::InCombatMap(look);/'
runm pb_scope_stale_believed $P 's/^  const bool in = scope::InCombatOrLobby(look);$/  const bool in = scope::SeenCombatOrLobby();/'
runm pb_scope_class_dropped $P 's/^  const scope::LookClass cls = scope::ClassOf(look);$/  const scope::LookClass cls = scope::LookClass::kOther;/'
runm pb_scope_live_unchecked $P '/^  if (!scope::Live()) return Refused("scope_not_live"/d'
runm pb_scope_live_token   $P 's/return Refused("scope_not_live", stage,/return Refused("module_not_loaded", stage,/'
runm pb_scope_live_after_image $P '/^  if (!scope::Live()) return Refused("scope_not_live"/d; s/^  if (std::strcmp(id, pinned::LibR15PatchedBuildId()) != 0) return Refused("build_id_mismatch", stage, kNothing);$/&\n  if (!scope::Live()) return Refused("scope_not_live", stage, kNothing);/'
