runm pb_cap_unannounced    $P 's/if (k == cap) {/if (false) {/'
runm pb_link_cap_early     $P 's/> kLinkCap) return;/>= kLinkCap) return;/'
runm pb_link_filter_short  $C 's/kLinkRepeatMs = 1000/kLinkRepeatMs = 100/'
