runm pb_decode_rez_lost    $R 's/    m.rez = rez ? 1 : 0;/    m.rez = 0;/'
runm pb_decode_rez_heal    $R 's/^    else return m;$/    else { m.rez = rez ? 1 : 0; return m; }/'
runm pb_decode_min         $R 's/if (a >= kUseBase \&\& a < kUseEnd) m.kind = kUse;/if (a > kUseBase \&\& a < kUseEnd) m.kind = kUse;/'
runm pb_decode_link_base   $R 's/const uint32_t v = BandValue(a - (m.kind == kUse ? kUseBase : kLinkBase));/const uint32_t v = BandValue(a - kUseBase);/'
