runm pb_hold_other_cs      $P 's/if (h.cs == cs \&\& NowMs()/if (NowMs()/'
runm pb_direct_any_kind    $P 's/if (inNode \&\& m.kind == kUse) {/if (inNode) {/'
runm pb_relayed_held       $P 's/if (inNode \&\& m.kind == kUse) {/if (m.kind == kUse) {/'
